@startuml

class Employee {
  + name : string
  + department : string
  + staffNumber : int
}

class IdentityCard {
  + cardNumber : int
}

class GuestCard {
  + cardNumber : int
  + date : date
}

class Car {
  + licensePlate : string
}

class CarPark {
  + isFull : boolean
}

class Barrier {
  + isRaised : boolean
}

class CardReader {
  + verify(card: IdentityCard) : boolean
}

class Reception {
  + collect(card: GuestCard) : void
}

Employee "1" -- "1" IdentityCard : wears
IdentityCard "1" -- "0..1" Car : used by
GuestCard "0..*" -- "0..1" Car : used by
Car "1" -- "1" Barrier : triggers
CarPark "1" -- "2" Barrier : has
CarPark "1" -- "1" CardReader : contains

@enduml

